using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEngine.SceneManagement;
public sealed class KingdomFollowupValidation:MonoBehaviour {
 const BindingFlags F=BindingFlags.NonPublic|BindingFlags.Instance;DungeonPrototype d;readonly List<string> results=new List<string>();string oldPath;public bool Done{get;private set;}public string Summary{get;private set;}
 object Get(string name){return typeof(DungeonPrototype).GetField(name,F).GetValue(d);}object Call(string name,params object[] args){return typeof(DungeonPrototype).GetMethod(name,F).Invoke(d,args);}void Check(bool ok,string text){results.Add((ok?"PASS ":"FAIL ")+text);}
 WorldDialogue Dialogue{get{return (WorldDialogue)Get("worldDialogue");}}
 IEnumerator FinishDialogue(){for(int i=0;i<200&&Dialogue.Active;i++){Dialogue.CompleteLetters();Dialogue.Advance(10000);yield return null;}Check(!Dialogue.Active,"Dialogue completes without blocking controls");}
 IEnumerator WaitScene(string path){float until=Time.realtimeSinceStartup+30;while((SceneManager.GetActiveScene().path!=path||DungeonWhiteTransition.Active)&&Time.realtimeSinceStartup<until)yield return null;Check(SceneManager.GetActiveScene().path==path&&!DungeonWhiteTransition.Active,"White transition reaches "+path);yield return null;}
 public void Run(){DontDestroyOnLoad(gameObject);StartCoroutine(Checks());}
 IEnumerator Checks(){oldPath=DungeonSaveStore.editorTestPath;DungeonSaveStore.editorTestPath=Path.GetFullPath("Tests/KingdomFollowupSave.json");try{yield return Work();}finally{DungeonSaveStore.editorTestPath=oldPath;Done=true;Summary=results.Count(r=>r.StartsWith("PASS"))+" passed / "+results.Count(r=>r.StartsWith("FAIL"))+" failed";File.WriteAllLines("Tests/KingdomFollowupResults.txt",new[]{Summary}.Concat(results));Debug.Log("Kingdom followup: "+Summary);}}
 IEnumerator Work(){var controller=UnityEngine.Object.FindFirstObjectByType<DigitalKingdomController>();d=controller.stateHost;var data=d.CaptureDungeonSave();var main=DungeonMapSettings.Current;data.city=new DigitalKingdomProgress{discovered=true,inCity=true,firstVisitCompleted=true,returnMapId=main.mapId,returnMap=main.name,returnScene="Assets/Scenes/SampleScene.unity",returnCell=main.startCell,returnHeading=main.startHeading};data.cell=main.startCell;data.heading=main.startHeading;data.interactions.completedEvents.Add("fixture.main.preserved");d.InitializeCityModel(data,controller.cityCamera);yield return null;
 var city=DigitalKingdomSettings.Current;var visible=city.locations.Where(l=>l!=null&&l.service!=DigitalKingdomService.Exit).ToArray();Check(Array.FindIndex(visible,l=>l.id=="city.dungeons")==Array.FindIndex(visible,l=>l.service==DigitalKingdomService.Sewers)+1,"Guide appears directly below RNG Sewers");var story=city.story;var state=(DigitalKingdomProgress)Get("cityProgress");Check(!CityNoticeSystem.Available(story.notices[0],state,visible),"Rumor NEW hidden before visiting every location");Check(((List<CityDungeonDestination>)Call("CityDungeonDestinations")).Count==0,"Kingdom unavailable before rumor and guide conversation");
 foreach(var location in visible){Check(d.OpenCityLocation(location.id),"Open destination "+location.id);yield return FinishDialogue();Call("LeaveCityLocation");}
 state=(DigitalKingdomProgress)Get("cityProgress");Check(state.visitedLocations.Count==visible.Length,"All destinations counted after dialogues and leaving");Check(CityNoticeSystem.Available(story.notices[0],state,visible),"NEW appears on The Last Life after all visits");Check(!CityNoticeSystem.Available(story.notices[1],state,visible),"Guide NEW waits for bar rumor");
 d.OpenCityLocation("city.inn");Check(Dialogue.Active&&Dialogue.Current.speaker=="POSADERO","NEW opens bartender rumor");yield return FinishDialogue();Call("LeaveCityLocation");Check(state.readNotices.Contains(story.notices[0].id)&&state.storyFlags.Contains("pixel.rumor.heard"),"Rumor completes and persists once");Check(CityNoticeSystem.Available(story.notices[1],state,visible),"NEW moves to dungeon guide");d.OpenCityLocation("city.dungeons");yield return FinishDialogue();Call("LeaveCityLocation");Check(state.storyFlags.Contains("pixel.route.unlocked"),"Guide unlocks real kingdom destination");Check(!CityNoticeSystem.Available(story.notices[1],state,visible),"Guide NEW removed after reading");int flags=state.storyFlags.Count;CityNoticeSystem.Read(story.notices[1],state);Check(flags==state.storyFlags.Count,"Repeated acknowledgement cannot duplicate flags");
 var custom=new CityNoticeRule{id="fixture.future",locationId="city.shop",requiredFlags=new[]{"pixel.route.unlocked"}};Check(CityNoticeSystem.Available(custom,state,visible),"Future notification rule works without controller edits");var legacy=JsonUtility.FromJson<DigitalKingdomProgress>("{}");CityNoticeSystem.Normalize(legacy);Check(legacy.storyFlags.Count==0&&legacy.visitedLocations.Count==0,"Old city saves normalize without inventing visits");
 var save=d.CaptureDungeonSave();DungeonSaveStore.Write(save,0,"Fixture");var loaded=DungeonSaveStore.Read(0);Check(loaded.city.readNotices.Count==2&&loaded.city.storyFlags.Contains("pixel.route.unlocked"),"Existing save store restores notification flags and reads");Check(loaded.city.visitedLocations.Count==visible.Length,"Visited destinations survive save/load");d.InitializeCityModel(loaded,controller.cityCamera);d.OpenCityLocation("city.dungeons");yield return FinishDialogue();Call("ExecuteCityService",0);yield return WaitScene("Assets/Scenes/RetroDungeonExperiment.unity");d=UnityEngine.Object.FindFirstObjectByType<RetroDungeonWallComposer>().dungeon;
 var composer=d.GetComponent<RetroDungeonWallComposer>();Check(d.mapSettings.mapId=="experiment.retro.luminous.v1","Guide loads independent kingdom map");Check(d.CanReturnToKingdom,"Pause can return to Digital Kingdom");Check(d.CaptureDungeonSave().maps.Any(m=>m.mapId==main.mapId&&m.interactions.completedEvents.Contains("fixture.main.preserved")),"Original dungeon snapshot preserved during kingdom visit");Check(d.CaptureEnemyProgression().Count(e=>string.IsNullOrEmpty(e.placementId))>0,"Normal enemies spawn in addition to pipe placements");Check(composer.settings.audioProfile.explorationPlaylist.All(c=>c!=null)&&composer.settings.audioProfile.normalCombatPlaylist.All(c=>c!=null),"Two exploration and two combat songs assigned");Check(composer.settings.normalMaps.Length==11&&composer.settings.normalMaps.All(n=>n.normal!=null),"Eleven actual normal-map imports assigned");Check(composer.GetComponentsInChildren<RetroDungeonPipe>().Count(p=>p.frontal)==2,"Two frontal pipe mouths installed");Check(d.ExplorationMinimapVisible,"Minimap visible outside battle");typeof(DungeonPrototype).GetField("battle",F).SetValue(d,true);Check(!d.ExplorationMinimapVisible,"Minimap hidden during battle");typeof(DungeonPrototype).GetField("battle",F).SetValue(d,false);Check(d.ExplorationMinimapVisible,"Minimap returns after battle");
 var kingdomSave=d.CaptureDungeonSave();kingdomSave.interactions.completedEvents.Add("fixture.kingdom.preserved");d.RestoreDungeonSave(kingdomSave);Check(d.ReturnFromKingdomDungeon(),"Return to city accepted");yield return WaitScene(city.scenePath);d=UnityEngine.Object.FindFirstObjectByType<DigitalKingdomController>().stateHost;var returned=d.CaptureDungeonSave();Check(returned.maps.Any(m=>m.mapId==kingdomSave.activeMapId&&m.interactions.completedEvents.Contains("fixture.kingdom.preserved")),"Kingdom snapshot preserved on return");Check(returned.city.readNotices.Count==2&&returned.city.returnMapId==main.mapId,"Notifications and original return anchor retained");d.OpenCityLocation("city.dungeons");yield return FinishDialogue();Call("ExecuteCityService",0);yield return WaitScene("Assets/Scenes/RetroDungeonExperiment.unity");d=UnityEngine.Object.FindFirstObjectByType<RetroDungeonWallComposer>().dungeon;Check(d.CaptureDungeonSave().interactions.completedEvents.Contains("fixture.kingdom.preserved"),"Revisiting kingdom restores its independent state");Check(d.ReturnFromKingdomDungeon(),"Second return accepted");yield return WaitScene(city.scenePath);
 }
}
